export type AgentResultStreamEvent = { "type": "result"; "subtype": string; "is_error": boolean; "result"?: string; "error"?: string; "interrupted"?: boolean; "session_id"?: string; "turn"?: number; "num_turns"?: number; "duration_ms"?: number; "tool_calls"?: number; "usage"?: JsonValue; "denials"?: Array<JsonValue>; };

export type AgentResumeAckStreamEvent = { "type": "resume_ack"; "token"?: string; "action"?: string; "session_id"?: string; };

export type AgentSessionErrorStreamEvent = { "type": "session_error"; "error"?: string; "message"?: string; };

export type AgentSlashCommandResultStreamEvent = { "type": "slash_command_result"; "request_id": string; "command": string; "ok": boolean; "text"?: string; "error"?: JsonValue; "session_id"?: string; };

export type AgentContentStreamEvent = { "type": "stream_event"; "event": JsonValue; };

export type AgentStreamRetryStreamEvent = { "type": "stream_retry"; "attempt"?: number; "message"?: string; };

export type AgentStructuredResultStreamEvent = { "type": "structured_result"; "schema_digest": Digest; "valid": boolean; "value": JsonValue; "errors"?: Array<JsonValue>; };

export type AgentSubagentCompletedStreamEvent = { "type": "subagent_completed"; "schema_version": 1; "subagent_id": string; "parent_id": string; "role"?: string; "status": "completed" | "failed"; "background": boolean; "iteration_count"?: number; };

export type AgentSubagentProgressStreamEvent = { "type": "subagent_progress"; "schema_version": 1; "subagent_id": string; "parent_id": string; "role"?: string; "event_type": string; "tool"?: string; "iteration_count"?: number; "token_count"?: number; };

export type AgentSubagentStartedStreamEvent = { "type": "subagent_started"; "schema_version": 1; "subagent_id": string; "parent_id": string; "role"?: string; "background": boolean; "max_iterations"?: number; };

export type AgentSystemStreamEvent = { "type": "system"; "subtype": string; "session_id"?: string; "model"?: string; "provider"?: string; "permission_mode"?: string; "tools"?: Array<string>; "slash_commands"?: Array<string>; "input_format"?: string; "additional_directories"?: Array<string>; "resumed_messages"?: number; "turns"?: number; "protocol_version"?: number | null; "features"?: Array<string>; "downgraded"?: boolean; "disabled_features"?: Array<string>; "ok"?: boolean; "reason"?: string | null; };

export type AgentTokenUsageStreamEvent = { "type": "token_usage"; "usage"?: JsonValue; };

export type AgentToolResultStreamEvent = { "type": "tool_result"; "id"?: string; "plan_item_id"?: string; "turn"?: number; "tool": string; "is_error"?: boolean; "error"?: string | null; "result"?: JsonValue; "permission_decision_id"?: string | null; "permission_decision"?: JsonValue; };

export type AgentToolUseStreamEvent = { "type": "tool_use"; "id"?: string; "plan_item_id"?: string; "turn"?: number; "tool": string; "args"?: JsonValue; };

export type AgentUserStreamEvent = { "type": "user"; "message"?: JsonValue; "session_id"?: string; };

export type AgentStreamEventPayload = AgentApprovalRequestStreamEvent | AgentApprovalResolvedStreamEvent | AgentCheckpointStreamEvent | AgentCompactionStreamEvent | AgentCompactionDegradedStreamEvent | AgentCompactionUsageUnknownStreamEvent | AgentCostBudgetExhaustedStreamEvent | AgentElicitationCompleteStreamEvent | AgentElicitationDeferredStreamEvent | AgentFeedbackAckStreamEvent | AgentHookProgressStreamEvent | AgentHookResponseStreamEvent | AgentHookStartedStreamEvent | AgentIterationBudgetExhaustedStreamEvent | AgentIterationWarningStreamEvent | AgentPlanUpdateStreamEvent | AgentQuestionRequestStreamEvent | AgentQuestionResolvedStreamEvent | AgentQuestionResponseRejectedStreamEvent | AgentRawStreamEvent | AgentRecoveryDegradedStreamEvent | AgentRemoteControlStreamEvent | AgentResultStreamEvent | AgentResumeAckStreamEvent | AgentSessionErrorStreamEvent | AgentSlashCommandResultStreamEvent | AgentContentStreamEvent | AgentStreamRetryStreamEvent | AgentStructuredResultStreamEvent | AgentSubagentCompletedStreamEvent | AgentSubagentProgressStreamEvent | AgentSubagentStartedStreamEvent | AgentSystemStreamEvent | AgentTokenUsageStreamEvent | AgentToolResultStreamEvent | AgentToolUseStreamEvent | AgentUserStreamEvent;

export type CanonicalAgentStreamEvent = (AgentStreamEventEnvelope) & (AgentStreamEventPayload);

export type InitializeParams = { "protocolVersion": number; "minimumProtocolVersion": number; "client": { "name": string; "version": string; }; "features"?: Array<string>; };

export type JsonRpcRequestBase = { "jsonrpc": "2.0"; "id": string | number; "method": string; "params"?: {  }; };

export type ClientRequest = (JsonRpcRequestBase) & ({ "method"?: "initialize"; "params"?: InitializeParams; } | { "method"?: "thread/start" | "thread/resume" | "thread/fork" | "thread/read" | "thread/list" | "thread/archive" | "turn/start" | "turn/interrupt" | "graph/compile" | "graph/run" | "graph/status" | "graph/history" | "graph/cancel" | "graph/reconcile"; });

export type ClientResponse = unknown | unknown;

export type ServerRequest = { "jsonrpc": "2.0"; "id": string | number; "method": "approval/decide" | "humanTask/decide"; "params": JsonValue; };

export type ServerNotification = { "jsonrpc": "2.0"; "method": "thread/updated" | "turn/started" | "turn/completed" | "item/started" | "item/delta" | "item/completed" | "approval/requested" | "approval/resolved" | "tool/requested" | "tool/result" | "subagent/started" | "subagent/completed" | "graph/event"; "params": JsonValue; };
